!**********************************************************************************************************************************
! UMM_Pressure Module
! Unified Momentum Model (UMM) Module for OpenFAST Implementation
!
! This module contains:
!   - Pressure table data for nonlinear pressure correction (originally generated as CSV from https://github.com/Howland-Lab/Unified-Momentum-Model/)
!   - Uses bilinear interpolation of pre-cached pressure lookup table instead of re-calculating the pressure table with each run
!   - (For Python code to solve and generate the pressure table, see: https://github.com/Howland-Lab/Unified-Momentum-Model/blob/main/UnifiedMomentumModel/Pressure/PressureSolver.py)
!
! Reference Paper: Liew et al. 2024 - https://www.nature.com/articles/s41467-024-50756-5
! Supplementaary Information Regararding Pressure Calculations: https://static-content.springer.com/esm/art%3A10.1038%2Fs41467-024-50756-5/MediaObjects/41467_2024_50756_MOESM1_ESM.pdf 
! Code Source (Python): https://github.com/Howland-Lab/Unified-Momentum-Model/blob/main/UnifiedMomentumModel/Pressure/PressureTable.py
!
!**********************************************************************************************************************************
module UMM_Pressure

   use NWTC_Library

   implicit none

   private

   !-------------------------------------------------------------------------------------------------
   ! Pressure table dimensions
