   integer(IntKi), public, parameter :: UMM_N_DP = 11    ! dp axis: 0.0, 0.1, ..., 1.0 (CT/2)
   integer(IntKi), public, parameter :: UMM_N_X  = 100   ! x axis: 100 points from 0.05 to 9.95 (rotor diameters downstream)

   !-------------------------------------------------------------------------------------------------
   ! dp (CT/2 or Δp/(ρ×u∞²)) axis values
